-- Seed ten fictional, public Explore examples. The placeholder creator phone is
-- reserved by the app and cannot be used to sign in. All sample source trips
-- are marked is_demo so they stay out of team demand metrics.
do $seed$
declare
  creator uuid;
  sample jsonb;
  trip_id uuid;
  destination text;
begin
  insert into public.users(first_name,last_name,phone)
  values ('Roam Sample','Library','+15550109990')
  on conflict (phone) do nothing;
  select id into creator from public.users where phone='+15550109990';

  for sample in
    select value from jsonb_array_elements($templates$
    [
      {"slug":"nyc-first-weekend","title":"New York, First Weekend","description":"Sample plan: skyline views, a neighborhood wander, a museum stop, and an easy final brunch.","tags":["City","Weekend","Food"],"season":"Fall","days":3,"price":"$$","cities":[{"city":"New York City","nights":3}],"blocks":[{"type":"activity","title":"Walk the High Line","note":"Enter near Hudson Yards and take your time heading downtown.","place":"The High Line","url":"https://www.thehighline.org/","day_index":1,"start_time":"14:00"},{"type":"food","title":"Dinner in the West Village","note":"Pick a cozy spot after the walk; book ahead for a group.","place":"West Village, New York","day_index":1,"start_time":"19:00"},{"type":"activity","title":"Museum morning","note":"Choose The Met or MoMA and leave room for a long lunch.","place":"Manhattan, New York","url":"https://www.metmuseum.org/","day_index":2,"start_time":"10:00"},{"type":"free_time","title":"Explore a neighborhood","note":"Split into small groups for shops, coffee, and photos.","place":"Brooklyn, New York","day_index":2,"start_time":"15:00"},{"type":"food","title":"Bagels before checkout","note":"Grab breakfast together, then head to the station or airport.","place":"New York City","day_index":3,"start_time":"09:00"}]},
      {"slug":"miami-beach-reset","title":"Miami Beach Reset","description":"Sample plan: beach time, a colorful Art Deco stroll, Cuban food, and one late night with plenty of downtime.","tags":["Beach","Nightlife","Food","Budget"],"season":"Spring","days":4,"price":"$$","cities":[{"city":"Miami Beach","nights":4}],"blocks":[{"type":"free_time","title":"Beach afternoon","note":"Bring water, sunscreen, and a shared umbrella.","place":"South Beach, Miami Beach","day_index":1,"start_time":"13:00"},{"type":"food","title":"Cuban dinner","note":"Share a few classic plates family-style.","place":"Little Havana, Miami","day_index":1,"start_time":"19:00"},{"type":"activity","title":"Art Deco walking loop","note":"Walk Ocean Drive and Collins Avenue before the heat peaks.","place":"Art Deco Historic District, Miami Beach","url":"https://mdpl.org/","day_index":2,"start_time":"10:00"},{"type":"free_time","title":"Pool and recharge","note":"Keep the afternoon open before going out.","place":"Miami Beach","day_index":2,"start_time":"15:00"},{"type":"nightlife","title":"Choose-your-own night out","note":"Agree on a meeting point and a ride home before splitting up.","place":"Miami Beach","day_index":3,"start_time":"21:00"},{"type":"food","title":"Brunch before heading out","note":"A slow final meal with the whole crew.","place":"Miami Beach","day_index":4,"start_time":"10:00"}]},
      {"slug":"montreal-food-music","title":"Montreal Food & Music","description":"Sample plan: old-town streets, a market picnic, a lookout, and a relaxed live-music night.","tags":["City","Food","Weekend"],"season":"Summer","days":3,"price":"$$","cities":[{"city":"Montreal","nights":3}],"blocks":[{"type":"activity","title":"Old Montreal wander","note":"Start at the waterfront and explore the historic streets on foot.","place":"Old Montreal","day_index":1,"start_time":"14:00"},{"type":"food","title":"Dinner near the old port","note":"Look for a patio and reserve for the group.","place":"Old Port of Montreal","day_index":1,"start_time":"19:00"},{"type":"food","title":"Jean-Talon Market picnic","note":"Everyone picks one snack to share in the park.","place":"Jean-Talon Market","url":"https://www.marchespublics-mtl.com/en/markets/jean-talon-market/","day_index":2,"start_time":"11:00"},{"type":"activity","title":"Mount Royal lookout","note":"Take the trail up and catch the city view.","place":"Mount Royal Park","day_index":2,"start_time":"16:00"},{"type":"nightlife","title":"Live music in the Plateau","note":"Check local listings and pick a show that works for everyone.","place":"Le Plateau-Mont-Royal, Montreal","day_index":2,"start_time":"20:30"},{"type":"food","title":"Coffee and pastries","note":"Easy breakfast before travel home.","place":"Montreal","day_index":3,"start_time":"09:00"}]},
      {"slug":"new-orleans-long-weekend","title":"New Orleans Long Weekend","description":"Sample plan: French Quarter history, beignets, a garden-district walk, and a jazz-filled evening.","tags":["Food","Nightlife","Weekend","City"],"season":"Spring","days":4,"price":"$$","cities":[{"city":"New Orleans","nights":4}],"blocks":[{"type":"food","title":"Beignets and coffee","note":"Go early to beat the busiest lines.","place":"French Quarter, New Orleans","day_index":1,"start_time":"09:00"},{"type":"activity","title":"French Quarter history walk","note":"Take a guided walking tour or make a self-guided route.","place":"French Quarter, New Orleans","day_index":1,"start_time":"11:00"},{"type":"food","title":"Casual po’boy lunch","note":"Keep lunch flexible while exploring downtown.","place":"New Orleans","day_index":2,"start_time":"12:30"},{"type":"activity","title":"Garden District stroll","note":"Walk under the oaks and admire the architecture.","place":"Garden District, New Orleans","day_index":2,"start_time":"15:00"},{"type":"nightlife","title":"Jazz set on Frenchmen Street","note":"Check the venue calendar and bring ID.","place":"Frenchmen Street, New Orleans","day_index":3,"start_time":"20:00"},{"type":"free_time","title":"Slow morning and checkout","note":"Leave a little buffer for travel and one last café stop.","place":"New Orleans","day_index":4,"start_time":"10:00"}]},
      {"slug":"mexico-city-art-eats","title":"Mexico City Art & Eats","description":"Sample plan: a central-history day, a museum and park afternoon, and a market-to-neighborhood food crawl.","tags":["City","Food","International"],"season":"Fall","days":4,"price":"$$","cities":[{"city":"Mexico City","nights":4}],"blocks":[{"type":"activity","title":"Historic center walk","note":"See the main plaza and nearby architecture at an easy pace.","place":"Centro Histórico, Mexico City","day_index":1,"start_time":"10:00"},{"type":"food","title":"Market lunch","note":"Choose a busy stall, order a few things to share, and keep water handy.","place":"Centro Histórico, Mexico City","day_index":1,"start_time":"13:00"},{"type":"activity","title":"Chapultepec and a museum","note":"Pick one museum, then unwind in the park.","place":"Bosque de Chapultepec","url":"https://mna.inah.gob.mx/","day_index":2,"start_time":"11:00"},{"type":"food","title":"Roma Norte dinner","note":"Book a table or make a shortlist with the group.","place":"Roma Norte, Mexico City","day_index":2,"start_time":"19:30"},{"type":"activity","title":"Coyoacán afternoon","note":"Explore the plazas, galleries, and cafés.","place":"Coyoacán, Mexico City","day_index":3,"start_time":"13:00"},{"type":"free_time","title":"Flexible final morning","note":"Leave space for a favorite repeat or a quiet coffee.","place":"Mexico City","day_index":4,"start_time":"09:30"}]},
      {"slug":"barcelona-dublin-spring","title":"Barcelona → Dublin Spring Break","description":"Sample plan: a week split between Barcelona’s architecture and beachside afternoons, then Dublin’s pubs, parks, and history.","tags":["Spring break","Multi-city","International","Food"],"season":"Spring","days":7,"price":"$$$","cities":[{"city":"Barcelona","nights":4},{"city":"Dublin","nights":3}],"blocks":[{"type":"activity","title":"Gothic Quarter wander","note":"Keep the first afternoon light and stop for snacks as you go.","place":"Barri Gòtic, Barcelona","day_index":1,"start_time":"15:00"},{"type":"food","title":"Tapas with the crew","note":"Order several small plates to share.","place":"Barcelona","day_index":1,"start_time":"20:00"},{"type":"activity","title":"Sagrada Família visit","note":"Reserve timed entry in advance.","place":"Sagrada Família, Barcelona","url":"https://sagradafamilia.org/en/","day_index":2,"start_time":"10:00"},{"type":"free_time","title":"Beach afternoon","note":"Take transit to the waterfront and leave the evening flexible.","place":"Barceloneta, Barcelona","day_index":3,"start_time":"14:00"},{"type":"travel","title":"Fly to Dublin","note":"Allow time for airport transit and check-in.","place":"Barcelona to Dublin","day_index":5,"start_time":"10:00"},{"type":"activity","title":"Trinity College and city center","note":"Explore the campus and nearby streets on foot.","place":"Trinity College Dublin","url":"https://www.tcd.ie/","day_index":5,"start_time":"15:00"},{"type":"food","title":"Dublin pub dinner","note":"Find a lively spot with food and music; check age policies.","place":"Dublin","day_index":6,"start_time":"19:00"},{"type":"activity","title":"Phoenix Park and final brunch","note":"Spend the morning outdoors before a relaxed meal.","place":"Phoenix Park, Dublin","day_index":7,"start_time":"10:00"}]},
      {"slug":"tokyo-neighborhood-sampler","title":"Tokyo Neighborhood Sampler","description":"Sample plan: an easy first week with distinct neighborhood days, a market breakfast, bright city nights, and quiet park time.","tags":["City","Food","International"],"season":"Spring","days":7,"price":"$$$","cities":[{"city":"Tokyo","nights":7}],"blocks":[{"type":"free_time","title":"Check in and explore nearby","note":"Stay close to your hotel on arrival day and find a convenience-store snack run.","place":"Tokyo","day_index":1,"start_time":"16:00"},{"type":"activity","title":"Asakusa and Senso-ji","note":"Go early, then wander the surrounding streets.","place":"Asakusa, Tokyo","day_index":2,"start_time":"09:00"},{"type":"food","title":"Market breakfast","note":"Try a few small bites and keep the route flexible.","place":"Toyosu, Tokyo","day_index":3,"start_time":"09:00"},{"type":"activity","title":"Meiji Shrine and Harajuku","note":"Pair a calm forest walk with nearby shops and cafés.","place":"Shibuya, Tokyo","day_index":4,"start_time":"10:00"},{"type":"nightlife","title":"Shinjuku evening","note":"Pick a meeting point and check the last train time before heading out.","place":"Shinjuku, Tokyo","day_index":5,"start_time":"19:00"},{"type":"free_time","title":"Choose your favorite neighborhood","note":"Leave this day open for a repeat visit or a day trip.","place":"Tokyo","day_index":6,"start_time":"11:00"},{"type":"food","title":"Last ramen stop","note":"One final crew meal before the airport run.","place":"Tokyo","day_index":7,"start_time":"11:00"}]},
      {"slug":"yosemite-cabin-weekend","title":"Yosemite Cabin Weekend","description":"Sample plan: a low-key cabin base, one big scenic day, shared meals, and an unhurried checkout.","tags":["Adventure","Weekend","Budget"],"season":"Summer","days":3,"price":"$$","cities":[{"city":"Yosemite National Park","nights":3}],"blocks":[{"type":"travel","title":"Drive in and stock up","note":"Coordinate cars, water, and groceries before entering the park.","place":"Yosemite National Park","day_index":1,"start_time":"12:00"},{"type":"food","title":"Shared cabin dinner","note":"Assign simple dishes before arrival and check kitchen supplies.","place":"Yosemite area","day_index":1,"start_time":"19:00"},{"type":"activity","title":"Valley viewpoints loop","note":"Choose a trail that fits the group's energy and current conditions.","place":"Yosemite Valley","url":"https://www.nps.gov/yose/planyourvisit/index.htm","day_index":2,"start_time":"08:00"},{"type":"free_time","title":"Cabin downtime","note":"Rest, play cards, or make an early dinner together.","place":"Yosemite area","day_index":2,"start_time":"17:00"},{"type":"food","title":"Breakfast and pack up","note":"Leave the cabin clean and allow extra time for the drive out.","place":"Yosemite area","day_index":3,"start_time":"08:00"}]},
      {"slug":"lisbon-porto-week","title":"Lisbon → Porto Week","description":"Sample plan: tiled streets, a riverside evening, a northbound rail day, and a final Porto food crawl.","tags":["Multi-city","Food","International","City"],"season":"Summer","days":6,"price":"$$$","cities":[{"city":"Lisbon","nights":3},{"city":"Porto","nights":3}],"blocks":[{"type":"activity","title":"Alfama and the viewpoints","note":"Wear comfortable shoes for the hills and take breaks for coffee.","place":"Alfama, Lisbon","day_index":1,"start_time":"15:00"},{"type":"food","title":"Riverside dinner","note":"Pick a spot near the water and watch the sunset.","place":"Cais do Sodré, Lisbon","day_index":1,"start_time":"19:30"},{"type":"activity","title":"Belém morning","note":"See the waterfront sights and try a local pastry.","place":"Belém, Lisbon","day_index":2,"start_time":"09:30"},{"type":"travel","title":"Train to Porto","note":"Book rail tickets ahead and leave room for station transfers.","place":"Lisbon to Porto","day_index":4,"start_time":"10:00"},{"type":"activity","title":"Ribeira and the riverfront","note":"Explore the old town and cross the bridge for a view.","place":"Ribeira, Porto","day_index":4,"start_time":"15:00"},{"type":"food","title":"Porto tasting menu or petiscos","note":"Choose a place with options for the whole group.","place":"Porto","day_index":5,"start_time":"20:00"},{"type":"free_time","title":"Coffee and final stroll","note":"Keep the last morning open before departure.","place":"Porto","day_index":6,"start_time":"09:00"}]},
      {"slug":"iceland-south-coast-road-trip","title":"Iceland South Coast Road Trip","description":"Sample plan: a flexible ring-road-inspired route with waterfalls, a glacier-view day, hot pools, and weather buffers.","tags":["Road trip","Adventure","International"],"season":"Summer","days":7,"price":"$$$","cities":[{"city":"Reykjavík","nights":2},{"city":"Vík","nights":2},{"city":"Reykjavík","nights":2}],"blocks":[{"type":"activity","title":"Reykjavík city walk","note":"Keep the arrival day easy and check local weather.","place":"Reykjavík","day_index":1,"start_time":"15:00"},{"type":"free_time","title":"Pick up the rental car","note":"Review insurance, road conditions, and fuel stops before leaving town.","place":"Reykjavík","day_index":2,"start_time":"09:00"},{"type":"activity","title":"Waterfalls along the south coast","note":"Leave time for short walks and changing weather.","place":"South Coast, Iceland","day_index":3,"start_time":"10:00"},{"type":"activity","title":"Glacier and black-sand coast","note":"Check access advisories and stay within marked safe areas.","place":"Vík, Iceland","day_index":4,"start_time":"09:00"},{"type":"free_time","title":"Weather buffer day","note":"Use this for a missed stop, a rest day, or a guided activity.","place":"South Coast, Iceland","day_index":5,"start_time":"10:00"},{"type":"travel","title":"Drive back to Reykjavík","note":"Allow generous driving time and return the car before the final night.","place":"Vík to Reykjavík","day_index":6,"start_time":"10:00"},{"type":"food","title":"Final crew dinner","note":"Celebrate the trip and leave time to pack.","place":"Reykjavík","day_index":6,"start_time":"19:00"}]}
    ]
    $templates$::jsonb) as rows(value)
  loop
    select string_agg(city->>'city',' → ' order by ordinality) into destination
    from jsonb_array_elements(sample->'cities') with ordinality as cities(city,ordinality);

    insert into public.trips(name,destination,commit_deadline,invite_code,created_by,is_demo,is_template_source,date_mode,planning_mode)
    values(sample->>'title',destination,current_date+90,'sample-'||(sample->>'slug'),creator,true,true,'unsure','manual')
    on conflict(invite_code) do update set name=excluded.name,destination=excluded.destination,is_demo=true,is_template_source=true,date_mode='unsure',planning_mode='manual'
    returning id into trip_id;

    insert into public.templates(source_trip_id,creator_user_id,creator_display_name,title,description,tags,season,days,cities_json,blocks_json,price_level,published,updated_at)
    values(trip_id,creator,'Roam Sample Library',sample->>'title',sample->>'description',array(select jsonb_array_elements_text(sample->'tags')),sample->>'season',(sample->>'days')::integer,sample->'cities',sample->'blocks',sample->>'price',true,now())
    on conflict(source_trip_id) do update set creator_user_id=excluded.creator_user_id,creator_display_name=excluded.creator_display_name,title=excluded.title,description=excluded.description,tags=excluded.tags,season=excluded.season,days=excluded.days,cities_json=excluded.cities_json,blocks_json=excluded.blocks_json,price_level=excluded.price_level,published=true,updated_at=now();
  end loop;
end
$seed$;
